{"file_path":"$PROJECT/code/pitch/components/IncomingCall.vue","content":"<script setup lang="ts">
import { onUnmounted, watch } from "vue";

/**
 * A chat-app style incoming call that slides in at the top right, with a synthesised ringtone
 * (Web Audio, no sound file). Rings only while `active`, and only where `sound` is set, so the
 * presenter view and the overview stay quiet.
 */
const props = withDefaults(defineProps<{ active: boolean; sound?: boolean; name?: string; initials?: string; role?: string }>(), {
  sound: true,
  name: "Tech lead",
  initials: "TL",
  role: "Incoming call…",
});

let ctx: AudioContext | undefined;
let timer: ReturnType<typeof setInterval> | undefined;

/** One ring: a short rising four-note phrase, soft attack and decay. */
function ring() {
  if (!ctx) return;
  const notes = [659.25, 783.99, 987.77, 1318.51]; // E5 G5 B5 E6
  const t0 = ctx.currentTime + 0.02;
  notes.forEach((f, i) => {
    const t = t0 + i * 0.16;
    for (const [mult, vol] of [[1, 0.16], [2, 0.04]] as const) {
      const o = ctx!.createOscillator();
      const g = ctx!.createGain();
      o.type = "sine";
      o.frequency.value = f * mult;
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(vol, t + 0.015);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.45);
      o.connect(g).connect(ctx!.destination);
      o.start(t);
      o.stop(t + 0.5);
    }
  });
}

function start() {
  if (!props.sound || timer) return;
  try {
    ctx ??= new AudioContext();
    void ctx.resume();
    ring();
    timer = setInterval(ring, 1600);
  } catch {
    /* no audio: the popover still shows */
  }
}

function stop() {
  if (timer) clearInterval(timer);
  timer = undefined;
  void ctx?.close();
  ctx = undefined;
}

watch(
  () => props.active,
  (on) => (on ? start() : stop()),
  { immediate: true },
);
onUnmounted(stop);
</script>

<template>
  <div class="call" :class="{ on: active }" role="dialog" aria-label="Incoming call">
    <div class="call-top">
      <span class="call-avatar">{{ initials }}<i class="pulse" /></span>
      <div class="call-who">
        <b>{{ name }}</b>
        <span>{{ role }}</span>
      </div>
    </div>
    <div class="call-actions">
      <button class="video" aria-label="Accept with video">
        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2zm14 3 4-2.5v9L17 14z" /></svg>
      </button>
      <button class="accept" aria-label="Accept">
        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.6 10.8a15.1 15.1 0 0 0 6.6 6.6l2.2-2.2a1 1 0 0 1 1-.25 11.4 11.4 0 0 0 3.6.57 1 1 0 0 1 1 1V20a1 1 0 0 1-1 1A17 17 0 0 1 3 4a1 1 0 0 1 1-1h3.5a1 1 0 0 1 1 1c0 1.25.2 2.45.57 3.57a1 1 0 0 1-.25 1z" /></svg>
      </button>
      <button class="decline" aria-label="Decline">
        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.6 10.8a15.1 15.1 0 0 0 6.6 6.6l2.2-2.2a1 1 0 0 1 1-.25 11.4 11.4 0 0 0 3.6.57 1 1 0 0 1 1 1V20a1 1 0 0 1-1 1A17 17 0 0 1 3 4a1 1 0 0 1 1-1h3.5a1 1 0 0 1 1 1c0 1.25.2 2.45.57 3.57a1 1 0 0 1-.25 1z" transform="rotate(135 12 12)" /></svg>
      </button>
    </div>
  </div>
</template>

